import type { ReactNode } from "react";
import { Chip } from "@repo/design-system/components/ui/chip";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@repo/design-system/components/ui/table";
import { Play } from "lucide-react";
import {
  HarnessBadge,
  SessionStatusBadge,
  ToneBadge,
} from "../primitives/status-badge";
import type { SessionRow } from "../types";
import {
  formatCurrency,
  formatDateTime,
  formatRelativeLabel,
  formatTokenCount,
  truncateMiddle,
} from "../utils";

type SessionTableProps = {
  rows: SessionRow[];
  emptyState?: ReactNode;
  getSessionHref?: (row: SessionRow) => string | undefined;
  renderSessionLink?: (row: SessionRow) => ReactNode;
  extraColumnLabel?: string;
  renderExtraColumn?: (row: SessionRow) => ReactNode;
};

export function SessionTable({
  rows,
  emptyState,
  getSessionHref,
  renderSessionLink,
  extraColumnLabel,
  renderExtraColumn,
}: SessionTableProps) {
  if (rows.length === 0) {
    return (
      emptyState ?? (
        <div className="px-6 py-12 text-center text-muted-foreground text-sm">
          No sessions match the current filters.
        </div>
      )
    );
  }

  return (
    <Table>
      <TableHeader className="bg-muted/30">
        <TableRow>
          <TableHead>Session</TableHead>
          <TableHead>Status</TableHead>
          <TableHead>Last activity</TableHead>
          <TableHead>Duration</TableHead>
          <TableHead className="text-right">Tokens</TableHead>
          <TableHead className="text-right">Agents</TableHead>
          <TableHead className="text-right">Cost</TableHead>
          <TableHead>Directory</TableHead>
          {extraColumnLabel ? <TableHead>{extraColumnLabel}</TableHead> : null}
        </TableRow>
      </TableHeader>
      <TableBody>
        {rows.map((row) => {
          const href = getSessionHref?.(row);
          return (
            <TableRow key={row.id}>
              <TableCell className="align-top">
                <div className="flex min-w-[14rem] flex-col gap-2">
                  <div className="font-medium">
                    {renderSessionLink
                      ? renderSessionLink(row)
                      : href
                        ? <a className="hover:underline" href={href}>{row.name}</a>
                        : row.name}
                  </div>
                  <div className="font-mono text-[11px] text-muted-foreground">
                    {row.id.slice(0, 12)}
                  </div>
                  <div className="flex flex-wrap gap-2">
                    <HarnessBadge harness={row.harness} />
                    <Chip variant="outline">{row.model}</Chip>
                    {row.isRunDriven ? (
                      <Chip asChild interactive variant="success">
                        <a href={row.runHref || "#"}>
                          <Play className="size-3" />
                          Run
                        </a>
                      </Chip>
                    ) : null}
                    {row.awaitingInputSince ? (
                      <ToneBadge
                        label="Awaiting input"
                        pulse
                        tone="accent"
                      />
                    ) : null}
                  </div>
                </div>
              </TableCell>
              <TableCell className="align-top">
                <SessionStatusBadge status={row.status} />
              </TableCell>
              <TableCell className="align-top">
                <div className="text-sm">
                  {formatRelativeLabel(row.lastActivity)}
                </div>
                <div className="text-muted-foreground text-xs">
                  {formatDateTime(row.lastActivity)}
                </div>
              </TableCell>
              <TableCell className="align-top font-mono text-xs">
                {row.durationLabel || "Running"}
              </TableCell>
              <TableCell className="text-right align-top tabular-nums">
                {row.totalTokens == null ? "—" : formatTokenCount(row.totalTokens)}
              </TableCell>
              <TableCell className="text-right align-top tabular-nums">
                {row.agents}
              </TableCell>
              <TableCell className="text-right align-top tabular-nums">
                {formatCurrency(row.cost)}
              </TableCell>
              <TableCell className="align-top">
                <div className="font-medium text-sm">
                  {truncateMiddle(row.repo, 36)}
                </div>
                <div className="text-muted-foreground text-xs">
                  Started {formatDateTime(row.startedAt)}
                </div>
              </TableCell>
              {extraColumnLabel ? (
                <TableCell className="align-top">
                  {renderExtraColumn?.(row) ?? null}
                </TableCell>
              ) : null}
            </TableRow>
          );
        })}
      </TableBody>
    </Table>
  );
}
